/* NJ Drive — local-first practice app */
(()=>{'use strict';
const C=NJCore,B=NJ_BANK.questions,byId=Object.fromEntries(B.map(q=>[q.id,q])),$=s=>document.querySelector(s),KEY='nj-drive-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=C.fresh(),storageOk=true,original=null,rawFocus=null,wrongArchived=false,filter={search:'',category:'all',source:'all',progress:'all'},listPage=1,reviewExam=null,reviewIndex=0,installPrompt=null;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);state=C.validateImport(parsed,B);if(parsed.session&&validSession(parsed.session))state.session=parsed.session;}}catch(e){storageOk=false;}
function validSession(s){return s&&typeof s.id==='string'&&['all','random','wrong','stars','topic','mock'].includes(s.mode)&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.length<=B.length&&new Set(s.ids).size===s.ids.length&&s.ids.every(id=>byId[id])&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.ids.length&&s.answers&&typeof s.answers==='object'&&Object.entries(s.answers).every(([id,a])=>s.ids.includes(id)&&Number.isInteger(a)&&a>=0&&a<4)&&s.recorded&&typeof s.recorded==='object'&&Number.isFinite(s.startedAt)&&(s.deadline===null||Number.isFinite(s.deadline))&&(!s.completed||s.mode!=='mock'||(s.result&&Number.isInteger(s.result.score)));}
function save(){state.updatedAt=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state));storageOk=true;}catch(e){storageOk=false;toast('浏览器未能保存，请立即到“设置与备份”导出学习记录。');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function fmtDate(t){return new Date(t).toLocaleDateString('zh-CN',{month:'short',day:'numeric'});}
function lang(v){if(typeof v==='string')return esc(v);const l=state.language;const primary=l==='en'?(v.en||v.zh):(v.zh||v.en);const secondary=l==='both'&&v.en&&v.zh?v.en:'';return esc(primary)+(secondary?`<span class="translation" lang="en">${esc(secondary)}</span>`:'');}
function title(q){return state.language==='en'?(q.stem.en||q.stem.zh):(q.stem.zh||q.stem.en);}
function wrongIds(archived=false){return B.filter(q=>archived?state.archive[q.id]:state.records[q.id]?.wrong).map(q=>q.id);}
function totals(){const rs=Object.values(state.records),attempts=rs.reduce((a,r)=>a+r.attempts,0),correct=rs.reduce((a,r)=>a+r.correct,0);return {done:rs.length,attempts,correct,accuracy:attempts?Math.round(correct/attempts*100):0,wrong:wrongIds().length};}
const topics=['行车规则','路标与信号','停车与转弯','让行与共享道路','安全与应急','酒精与药物','驾照与GDL'];
const icons=['↗','◈','↶','⇄','⊕','◉','▣'];
const routes=[['home','⌂','学习首页'],['practice','▤','全题练习'],['mock','◷','模拟考试'],['wrong','↻','错题本'],['library','▦','题库浏览'],['stats','▥','学习统计'],['settings','⚙','设置与备份']];
function nav(page){$('#nav').innerHTML=routes.map(([id,ic,label],i)=>`<a href="#${id}" ${i>4?'data-extra':''} class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} title="${label}"><span class="nav-icon" aria-hidden="true">${ic}</span><span>${label}</span>${id==='wrong'&&wrongIds().length?`<span class="nav-count">${wrongIds().length}</span>`:''}</a>`).join('');$('#language').value=state.language;$('#page-title').textContent=routes.find(r=>r[0]===page)?.[2]||'题库来源';}
function intro(h,p,extra=''){return `<div class="intro"><div><h1>${h}</h1><p class="muted">${p}</p></div>${extra}</div>`;}
function button(text,action,cls=''){return `<button class="btn ${cls}" data-action="${action}">${text}</button>`;}
function empty(h,p,action=''){return `<div class="panel empty"><span class="topic-icon" style="margin:0 auto">✓</span><h2>${h}</h2><p>${p}</p>${action}</div>`;}
function metric(label,value,note){return `<div class="metric"><div class="metric-label">${label}<span aria-hidden="true">↗</span></div><strong>${value}</strong><small>${note}</small></div>`;}
function home(){const t=totals(),pct=Math.round(t.done/B.length*100),s=state.session;return intro('每一道练习，都离驾照更近。','中英双语题库，把知识变成上路的信心。',`<span class="pill"><span class="dot"></span> 2026 手册已接入</span>`)+`<div class="hero"><section class="hero-card"><span class="eyebrow">READY FOR THE REAL THING?</span><h2>下一站，顺利通过。</h2><p>用一场完整模拟，检验你的准备。<br>从已核对题库抽取 50 题，答题后立即看解析。</p><a class="btn" href="#mock">开始模拟考试 <span>↗</span></a><div class="hero-stats"><span><strong>50</strong>道考题</span><span><strong>40</strong>道通过</span><span><strong>80%</strong>及格线</span></div><svg class="road" viewBox="0 0 160 250" aria-hidden="true"><path d="M30 280C200 155-50 120 190-20" fill="none" stroke="#517d74" stroke-width="76"/><path d="M30 280C200 155-50 120 190-20" fill="none" stroke="#bbd0a7" stroke-width="2" stroke-dasharray="15 15"/><circle cx="132" cy="110" r="17" fill="#e2b47b"/><path d="m124 111 5 5 9-11" stroke="#173e42" stroke-width="3" fill="none"/></svg></section><section class="journey-card"><div><span class="eyebrow">ONE QUESTION AT A TIME</span><h3>${s&&!s.completed?'接着上次的进度。':'先刷一题，进入状态。'}</h3><p>${s&&!s.completed?`已作答 ${Object.keys(s.answers).length} / ${s.ids.length} 题`:`共 ${B.length} 道选择题，随时开始，随时继续。`}</p></div><div><div class="progress-row"><span>题库覆盖进度</span><b>${pct}%</b></div><div class="progress"><span style="width:${pct}%"></span></div><div class="progress-row muted"><span>已练 ${t.done} 题</span><span>共 ${B.length} 题</span></div></div><div>${button(s&&!s.completed?'继续上次练习 →':'开始全题练习 →',s&&!s.completed?'resume':'all','secondary')}</div></section></div><div class="metric-grid">${metric('累计练习',t.done+' <small>题</small>','按不重复题目统计')}${metric('答题正确率',t.accuracy+'%','累计 '+t.attempts+' 次作答')}${metric('待复习错题',t.wrong+' <small>题</small>','连续答对 2 次自动归档')}${metric('模拟通过',state.exams.filter(e=>e.passed).length+' <small>次</small>','共完成 '+state.exams.length+' 次模拟')}</div><div class="section-head"><h2>按知识点，逐个突破</h2><a href="#library">查看全部题库 ↗</a></div><div class="topic-grid">${topics.map((topic,i)=>{const qs=B.filter(q=>q.category===topic),done=qs.filter(q=>state.records[q.id]).length;return `<button class="topic-card" data-action="topic" data-value="${topic}"><span class="topic-icon" aria-hidden="true">${icons[i]}</span><h3>${topic}</h3><p>${qs.length} 题 · 已练 ${done} 题</p><div class="progress"><span style="width:${done/Math.max(1,qs.length)*100}%"></span></div></button>`;}).join('')}<a class="topic-card" href="#wrong"><span class="topic-icon" style="background:#f8eade" aria-hidden="true">↻</span><h3>错题专项复习</h3><p>每次回顾，都有新的进步</p><span class="hint">去复习 →</span></a></div><div class="callout">判分题库共 ${B.length} 道，均附官方依据。已修订 ${NJ_BANK.meta.rewritten} 道原题；${NJ_BANK.meta.retired} 道因缺图、条件不足或依据不充分移至资料区。<a href="#sources"><u>查看来源与修订记录</u></a>。</div>`;}
function filtersHtml(){return `<div class="filters"><input id="search" aria-label="搜索题目" placeholder="搜索中文、English 或题号…" value="${esc(filter.search)}"><select id="category" aria-label="题目分类"><option value="all">全部知识点</option>${topics.map(t=>`<option ${filter.category===t?'selected':''}>${t}</option>`).join('')}</select><select id="source-filter" aria-label="核对状态"><option value="all" ${filter.source==='all'?'selected':''}>全部题库</option><option value="verified" ${filter.source==='verified'?'selected':''}>已核对题目</option><option value="revised" ${filter.source==='revised'?'selected':''}>已修订原题</option><option value="added" ${filter.source==='added'?'selected':''}>公开资料新增</option><option value="stars" ${filter.source==='stars'?'selected':''}>我的收藏</option></select><select id="progress-filter" aria-label="练习进度"><option value="all">全部进度</option><option value="new" ${filter.progress==='new'?'selected':''}>尚未练习</option><option value="done" ${filter.progress==='done'?'selected':''}>已经练习</option></select></div>`;}
function filtered(){const needle=filter.search.trim().toLowerCase();return B.filter(q=>(filter.category==='all'||q.category===filter.category)&&(filter.source==='all'||filter.source==='verified'&&q.verified||filter.source==='revised'&&q.correction||filter.source==='added'&&q.id.startsWith('mvc-')||filter.source==='stars'&&state.stars.includes(q.id))&&(filter.progress==='all'||filter.progress==='new'&&!state.records[q.id]||filter.progress==='done'&&state.records[q.id])&&(!needle||JSON.stringify([q.id,q.stem,q.options]).toLowerCase().includes(needle)));}
function practiceLanding(){const ids=filtered().map(q=>q.id);return intro('全题练习','按顺序刷完、随机练习，或挑一个知识点开始。')+filtersHtml()+`<section class="panel"><h2>准备好开始了吗？</h2><p class="muted">当前筛选 ${ids.length} 题。练习时即时查看答案与解析，进度自动保存。</p><div class="actions">${button('顺序全刷 →','filtered')}${button('随机 20 题','random','secondary')}${state.session&&!state.session.completed?button('继续上次练习','resume','secondary'):''}</div><div class="callout">全部判分题目已对照官方资料核对；原题错误已修正。缺图或无法确定唯一答案的题仅保留在原文对照，不影响成绩和错题统计。</div></section>`+questionList(filtered().slice(0,10),'preview');}
function images(q){return q.images?.length?`<div class="question-images">${q.images.map(src=>`<img src="${esc(src)}" alt="${esc(q.category==='路标与信号'?'本题交通标志图':'本题道路场景示意图')}" loading="lazy">`).join('')}</div>`:'';}
function explanation(q,answer){const correct=answer===q.answer,chosen=Number.isInteger(answer)&&q.options[answer];return `<section id="answer-explanation" class="explanation ${correct?'':'error'}" role="region" aria-labelledby="feedback-title" tabindex="-1"><h3 id="feedback-title">${correct?'✓ 回答正确':chosen?'答错了，正确答案是 '+String.fromCharCode(65+q.answer):'未作答，正确答案是 '+String.fromCharCode(65+q.answer)}</h3>${chosen&&!correct?`<div class="feedback-choice your-choice"><span>你的选择 · ${'ABCD'[answer]}</span><div>${lang(chosen)}</div></div>`:''}<div class="feedback-choice right-choice"><span>正确答案 · ${'ABCD'[q.answer]}</span><div>${lang(q.options[q.answer])}</div></div><h4>为什么选这个？</h4><p class="feedback-rule">${esc(q.explanation)}</p>${q.optionExplanations?.[answer]&&!correct?`<h4>你的选项错在哪？</h4><p>${esc(q.optionExplanations[answer])}</p>`:''}${q.correction?`<div class="feedback-correction"><b>原题修订说明：</b>${esc(q.correction)}</div>`:''}<div class="source">${esc(q.source)}${q.page?' · 手册印刷页 '+q.page:''}${q.sourceUrl?` · <a href="${esc(q.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看官方依据 ↗</a>`:''}${q.rawId?` · <button class="text-link" data-action="raw" data-value="${q.rawId}">对照原文</button>`:''}</div><div class="hint">${correct?'记住规则，下次换一种问法也能做对。':'本题已自动收录错题本；理解规则后再练，连续答对两次会归档。'}</div></section>`;}
function revealFeedback(){requestAnimationFrame(()=>{const el=$('#answer-explanation');if(el){el.scrollIntoView({behavior:'smooth',block:'start'});el.focus({preventScroll:true});}});}

function questionMarkup(q,answer,show,exam=false){return `<div class="tag-row"><span class="badge">${esc(q.category)}</span><span class="badge">${esc(q.id)}</span><span class="pill ${q.verified?'':'warn'}">${q.verified?'已核对':'原文待核对'}</span><button class="star" data-action="star" data-value="${q.id}" aria-label="${state.stars.includes(q.id)?'取消收藏':'收藏本题'}">${state.stars.includes(q.id)?'★':'☆'}</button></div><div class="question">${lang(q.stem)}</div>${images(q)}<div class="options">${q.options.map((o,i)=>`<button class="option ${answer===i?'selected':''} ${show?(i===q.answer?'correct':answer===i?'incorrect':''):''}" data-action="answer" data-value="${i}" ${show?'disabled':''} aria-pressed="${answer===i}"><span class="letter">${'ABCD'[i]}</span><span>${lang(o)}</span>${show&&i===q.answer?'<span style="margin-left:auto">✓</span>':''}</button>`).join('')}</div>${show?explanation(q,answer):''}${!q.verified&&!show?'<p class="hint">此题按上传文档答案判分，尚未核对现行规则。</p>':''}`;}
function quiz(){const s=state.session;if(!s)return practiceLanding();if(s.completed&&s.mode==='mock')return result(s.result);const q=byId[s.ids[s.index]],a=s.answers[q.id],exam=s.mode==='mock',show=(!exam||s.feedback==='immediate')&&!!s.recorded[q.id];const answered=Object.keys(s.answers).length;return intro(exam?'模拟考试':'专注这一题。',exam?(s.feedback==='immediate'?'学习模拟 · 作答后立即解析 · 每题首次作答计分':'考试模拟 · 可修改答案 · 交卷后统一解析'):'答错后立即显示正确答案和规则解析，并自动加入错题本。')+`<div class="two-col"><section class="panel"><div class="quiz-head"><span>${exam?(s.feedback==='immediate'?'学习模拟':'考试模拟'):'PRACTICE'} · 第 ${s.index+1} / ${s.ids.length} 题</span>${exam?'<span class="timer" id="timer">'+timeLeft(s)+'</span>':`<span>已答 ${answered} 题</span>`}</div><div class="progress"><span style="width:${answered/s.ids.length*100}%"></span></div><div class="spacer"></div>${questionMarkup(q,a,show,exam)}${exam&&s.feedback!=='immediate'?'<p class="hint">想每题作答后立即看解析？<button class="text-link" data-action="enable-feedback">切换学习模拟</button>（已选答案将锁定并按首次记录计分）</p>':''}<div class="quiz-actions"><div class="actions"><button class="btn secondary" data-action="prev" ${s.index===0?'disabled':''}>← 上一题</button><button class="btn secondary" data-action="next" ${s.index===s.ids.length-1?'disabled':''}>下一题 →</button></div><button class="btn secondary mobile-label" data-action="map">答题卡</button>${exam?button('交卷','submit'):s.index===s.ids.length-1?button('完成本轮','finish'):button('退出并保存','exit','secondary')}</div></section><aside class="panel side-panel quiz-map"><h3>答题卡</h3><p>${exam?'绿色为已选择答案。考试可暂离，计时继续。':'点击题号跳转。绿色为答对，浅红为答错。'}</p><div class="number-grid">${s.ids.map((id,i)=>`<button data-action="jump" data-value="${i}" aria-label="第 ${i+1} 题" class="${i===s.index?'current':''} ${s.answers[id]!==undefined?'done':''} ${!exam&&s.recorded[id]&&s.answers[id]!==byId[id].answer?'bad':''}">${i+1}</button>`).join('')}</div><div class="spacer"></div><p>收藏题目，随时回看。<br>语言切换不会清除答题进度。</p></aside></div>`;}
function timeLeft(s){if(!s.deadline)return '不限时';const sec=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
function mockLanding(){const s=state.session;return intro('在这里，练习正式上场。','默认学习模拟，每道题作答后立即显示解析；也可选择交卷后统一解析。')+`<div class="two-col"><section class="panel"><span class="pill">MVC 普通汽车知识考试标准</span><h2 style="margin-top:25px;font-size:28px">50 道题，检验你的准备。</h2><p class="muted">答对至少 40 题即通过。学习模拟会即时解析并锁定本题答案；考试模拟可改答案，交卷后统一解析。漏答按错题计分。</p><div class="metric-grid" style="grid-template-columns:repeat(3,1fr)">${metric('题目数量','50','随机抽取，不重复')}${metric('及格分数','80%','至少答对 40 题')}${metric('已核对题池',NJ_BANK.meta.verified,'含官方公开样题考点')}</div><label class="hint" for="mock-feedback">解析方式</label><div class="actions" style="margin:10px 0 20px"><select id="mock-feedback"><option value="immediate">学习模拟：作答后立即解析</option><option value="exam">考试模拟：交卷后解析</option></select></div><label class="hint" for="exam-time">练习计时（自选设置，并非官方时限）</label><div class="actions" style="margin:10px 0 25px"><select id="exam-time"><option value="60">60 分钟</option><option value="45">45 分钟</option><option value="30">30 分钟</option><option value="0">不限时</option></select></div><div class="actions">${button('开始一场新模拟 →','new-mock')}${s&&s.mode==='mock'&&!s.completed?button('继续未完成模拟','resume','secondary'):''}</div><p class="hint" style="margin-top:20px">倒计时使用实际经过时间，离开页面后继续；到时自动交卷。考试记录与错题保存在当前浏览器。</p></section><aside class="panel side-panel"><h3>最近考试</h3>${state.exams.slice(0,5).map(e=>`<div class="list-card" style="padding:12px"><div><p>${fmtDate(e.finishedAt)} · ${e.passed?'通过':'未通过'}</p><h3>${e.score} / 50</h3></div><button class="text-link" data-action="history" data-value="${esc(e.id)}">复盘</button></div>`).join('')||'<p>完成第一场模拟，<br>留下你的进步记录。</p>'}</aside></div>`;}
function result(e){const skipped=e.ids.filter(id=>e.answers[id]===undefined).length;return intro('考试结果','每一次复盘，都会让下一次更有把握。')+`<section class="panel result ${e.passed?'':'fail'}"><div class="score-ring"><strong>${e.score*2}%</strong><span>${e.score} / ${e.total} 题</span></div><h2>${e.passed?'这次模拟，通过了。':'再练一轮，离通过更近。'}</h2><p class="muted">${e.feedback==='immediate'?'学习模拟':'考试模拟'} · 及格线 40 / 50 · ${skipped} 题未作答 · 用时 ${Math.floor(e.duration/60000)} 分 ${Math.floor(e.duration/1000)%60} 秒${e.reason==='timeout'?' · 计时结束自动交卷':''}</p><div class="actions">${button('逐题查看解析','review')}${button('复习本次错题','exam-wrong','secondary')}<a href="#mock" class="btn secondary">返回模拟考试</a></div><p class="hint" style="margin-top:20px">本次答错与漏答题已自动加入错题本。</p></section>`;}
function review(){const e=reviewExam||state.session?.result;if(!e)return mockLanding();const q=byId[e.ids[reviewIndex]],a=e.answers[q.id];return intro('逐题复盘',`第 ${reviewIndex+1} / ${e.total} 题 · ${a===undefined?'未作答':a===q.answer?'回答正确':'回答错误'}`)+`<section class="panel">${questionMarkup(q,a,true)}<div class="quiz-actions"><button class="btn secondary" data-action="review-prev" ${reviewIndex===0?'disabled':''}>← 上一题</button><button class="btn secondary" data-action="review-next" ${reviewIndex===e.ids.length-1?'disabled':''}>下一题 →</button><a class="btn" href="#mock">返回模拟考试</a></div></section>`;}
function questionList(qs,kind='library'){return qs.map(q=>{const r=state.records[q.id];return `<article class="list-card"><div><div class="tag-row" style="margin-bottom:7px"><span class="badge">${esc(q.category)}</span><span class="badge">${esc(q.id)}</span><span class="hint">${q.verified?'已核对':'原文待核对'}</span></div><h3>${esc(title(q))}</h3><p>${r?`练习 ${r.attempts} 次 · 错 ${r.errors} 次${r.wrong?' · 复习连续答对 '+r.streak+'/2':''}`:'尚未练习'}${state.stars.includes(q.id)?' · ★ 已收藏':''}</p></div><button class="btn secondary small" data-action="single" data-value="${q.id}">${kind==='wrong'?'复习':'练习'}</button></article>`;}).join('');}
function wrong(){const archived=wrongArchived,ids=wrongIds(archived),qs=ids.map(id=>byId[id]).sort((a,b)=>(state.records[b.id]?.errors||0)-(state.records[a.id]?.errors||0));return intro('把错题，变成会做的题。','作答错误自动收录；连续两次答对后自动归档，再次答错会重新加入。')+`<div class="section-head"><div class="actions"><button class="btn ${archived?'secondary':''} small" data-action="wrong-active">待复习 ${wrongIds().length}</button><button class="btn ${archived?'':'secondary'} small" data-action="wrong-archived">已归档 ${wrongIds(true).length}</button></div><button class="btn small" data-action="wrong-start" ${ids.length?'':'disabled'}>${archived?'再练归档题':'开始错题复习'} →</button></div>`+(qs.length?questionList(qs,'wrong'):empty(archived?'还没有归档的错题':'暂时没有待复习错题',archived?'复习中连续答对两次，就会出现在这里。':'继续练习，系统会帮你记录每一个需要回顾的知识点。','<a class="btn" href="#practice">开始练习 →</a>'));}
function library(){const qs=filtered(),pages=Math.max(1,Math.ceil(qs.length/20));listPage=Math.min(listPage,pages);return intro('你的驾考知识库。',`${B.length} 道选择题 · 支持中英文搜索、分类和收藏`)+filtersHtml()+`<div class="section-head"><span class="hint">找到 ${qs.length} 题 · 第 ${listPage}/${pages} 页</span><button class="text-link" data-action="original">查看完整原文（含简答与待整理内容） ↗</button></div>`+(qs.length?questionList(qs.slice((listPage-1)*20,listPage*20)):empty('没有匹配的题目','试试其他关键词或调整筛选。'))+`<div class="page-links"><button class="btn secondary small" data-action="page-prev" ${listPage<=1?'disabled':''}>← 上一页</button><span>${listPage} / ${pages}</span><button class="btn secondary small" data-action="page-next" ${listPage>=pages?'disabled':''}>下一页 →</button><button class="btn small" data-action="filtered">练习筛选题目</button></div>`;}
async function originals(id){$('#main').innerHTML=intro('原文对照','上传文档的完整文本块与配图，保留原答案；仅供资料查阅。')+'<p>正在载入原文…</p>';try{if(!original){const r=await fetch('original.json');if(!r.ok)throw Error();original=await r.json();}const needle=filter.search.toLowerCase();const rows=id?original.filter(r=>r.id===id):original.filter(r=>!needle||r.text.toLowerCase().includes(needle));$('#main').innerHTML=intro('原文对照',`${rows.length} 个文本块 · 保留原文内容与答案，不计入答题统计`)+`<div class="actions" style="margin-bottom:20px"><a href="#library" class="btn secondary small">← 返回题库</a><input id="raw-search" aria-label="搜索原文" placeholder="搜索完整原文…" value="${esc(id?'':filter.search)}"><button class="btn small" data-action="raw-search">搜索</button></div><div class="callout" style="margin:0 0 20px">原资料存在过时法规、答案冲突和不完整题目。已修订的选择题以练习页的核对说明为准。此处展示的是原稿。</div>`+rows.slice(0,100).map(r=>`<details ${id?'open':''}><summary>${esc(r.id)} · ${esc(r.text.slice(0,95))}…</summary><div class="raw-text">${esc(r.text)}</div>${images(r)}</details>`).join('')+(rows.length>100?'<p class="hint">为保证流畅，最多显示 100 条；请用关键词定位。完整原始数据随源码包提供。</p>':'');}catch(e){$('#main').innerHTML=empty('原文暂时无法载入','请联网后重试。',button('重试','original'));}}
function stats(){const t=totals();return intro('看见自己的进步。','统计包含练习与已提交的模拟；模拟中的临时选择不会计入。')+`<div class="metric-grid">${metric('已练题目',t.done,B.length+' 题中的不重复题数')}${metric('累计作答',t.attempts,'每次有效作答计一次')}${metric('累计正确率',t.accuracy+'%',t.correct+' 次答对')}${metric('错题已归档',wrongIds(true).length,'每题连续答对两次')}</div><div class="settings-grid"><section class="panel"><h2>知识点覆盖</h2>${topics.map(t=>{const qs=B.filter(q=>q.category===t),done=qs.filter(q=>state.records[q.id]).length;return `<div class="chart-bar"><span>${t}</span><div class="progress"><span style="width:${done/qs.length*100}%"></span></div><b>${done}/${qs.length}</b></div>`;}).join('')}</section><section class="panel"><h2>模拟考试记录</h2>${state.exams.map(e=>`<div class="list-card"><div><h3>${e.score} / 50 · ${e.passed?'通过':'未通过'}</h3><p>${fmtDate(e.finishedAt)} · ${Math.floor(e.duration/60000)} 分钟</p></div><button class="text-link" data-action="history" data-value="${esc(e.id)}">查看</button></div>`).join('')||'<p class="hint">还没有完成的模拟考试。去检验一下学习成果吧。</p>'}</section></div>`;}
function settings(){return intro('随时学，也记得备份。','学习记录只保存在当前浏览器，不会自动同步到其他手机或电脑。')+`<div class="settings-grid"><section class="panel"><h2>安装到手机主屏幕</h2><p>Android：用 Chrome 打开正式网址，菜单中选择“安装应用”或“添加到主屏幕”。<br>iPhone：用 Safari 打开网址，点“分享”→“添加到主屏幕”。<br>电脑：在支持安装的浏览器地址栏点击安装图标。</p>${button('安装应用','install','secondary')}<p class="hint">首次联网载入后，题库和配图会缓存供离线练习。私密浏览、清理浏览器数据或更换设备会影响记录。安装能力由浏览器和站点访问环境决定。</p><div class="status" id="cache-status">正在检查离线缓存…</div></section><section class="panel"><h2>学习记录备份</h2><p>导出 JSON 备份，在另一台设备导入即可转移错题、收藏和成绩。导入会替换当前记录；导入前建议先导出。</p><div class="actions">${button('导出学习记录','export')}${button('导入备份','import','secondary')}</div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="hint">未完成的练习会留在当前浏览器；跨设备备份恢复的是已提交记录。</p></section><section class="panel"><h2>我的收藏</h2><p>已收藏 ${state.stars.length} 道题，在练习中点 ☆ 收藏。</p>${button('练习所有收藏题','stars','secondary')} <button class="text-link" data-action="star-list">浏览收藏</button></section><section class="panel"><h2>更多</h2><div class="actions"><a class="btn secondary" href="#stats">学习统计</a><a class="btn secondary" href="#sources">题库来源</a></div><p class="hint">版本 1.1.0 · 资料核对 ${NJ_BANK.meta.checkedAt}</p><button class="text-link" data-action="reset">清空本机学习记录</button></section></div>`;}
function sources(){return intro('每道题，都能找到依据。','这是一款独立练习工具，不代表 MVC，也不声称掌握正式考试完整题库。')+`<section class="panel"><h2>题库构成</h2><p>从你上传的中英双语 Word 中整理出 ${NJ_BANK.meta.imported} 道选择题，逐题核对后 ${NJ_BANK.meta.importedActive} 道保留或修订进入判分题库，${NJ_BANK.meta.retired} 道移至原文资料区。另有 ${NJ_BANK.meta.added} 道依据公开资料编写的双语练习题，判分题库共 ${B.length} 道。</p><p class="hint">导入时按规范化题干与首个选项去重；同知识点的不同问法会保留。原文件包含的 ${NJ_BANK.meta.rawBlocks} 个文本块（含简答、不完整题与重复题）可在“原文对照”查阅。未能可靠整理为四选一的内容不参与自动判分。图示题对照原图与标志资料检查；无法可靠对应的题已移出判分题库，仍可查阅原文。</p><p class="hint">已核对表示本次对照来源检查过答案，中文翻译与解析由本应用整理。规则可能更新；备考以 MVC 最新公开资料为准。</p></section><section class="panel"><h2>网上公开资料</h2>${NJ_BANK.sources.map(s=>`<div class="list-card"><div><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p>${esc(s.description)}</p></div></div>`).join('')}<p class="hint">核对日期：${NJ_BANK.meta.checkedAt}。驾驶手册为实际下载的 2026 英文版，共 243 PDF 页；题目所列“印刷页”与 PDF 页码相差 2 页。官方样题页包含旧的 two-second 表述，涉及跟车距离时采用 2026 手册的 three-second-plus 建议。</p></section><section class="panel"><h2>移至原文资料区的题目</h2><p class="hint">这些原题不用于判分，可按题号在完整原文查阅。</p>${(NJ_BANK.retired||[]).map(q=>`<div class="list-card"><div><h3>${esc(q.id)} · ${esc(q.stem.zh||q.stem.en)}</h3><p>${esc(q.reason)}</p></div><button class="text-link" data-action="raw" data-value="${q.rawId}">原文</button></div>`).join('')}</section><section class="panel"><h2>已修订的原题</h2>${B.filter(q=>q.correction).map(q=>`<div class="list-card"><div><h3>${esc(q.id)} · ${esc(title(q))}</h3><p>${esc(q.correction)}</p></div><button class="text-link" data-action="single" data-value="${q.id}">查看</button></div>`).join('')}</section>`;}
function render(){let page=location.hash.slice(1)||'home';nav(page);let html;switch(page){case'home':html=home();break;case'practice':html=practiceLanding();break;case'quiz':html=quiz();nav(state.session?.mode==='mock'?'mock':'practice');break;case'mock':html=mockLanding();break;case'wrong':html=wrong();break;case'library':html=library();break;case'stats':html=stats();break;case'settings':html=settings();break;case'sources':html=sources();break;case'result':html=reviewExam?result(reviewExam):state.session?.result?result(state.session.result):mockLanding();nav('mock');break;case'review':html=review();nav('mock');break;case'original':nav('library');originals(rawFocus);return;default:html=home();nav('home');}$('#main').innerHTML=html;if(!storageOk)$('#main').insertAdjacentHTML('afterbegin','<div class="storage-warning">本机存储不可用或原记录损坏，请在设置中导出备份。当前学习可能无法保留。</div>');if(page==='settings')cacheStatus();}
async function confirm(h,p){$('#confirm-title').textContent=h;$('#confirm-text').textContent=p;const d=$('#confirm');d.returnValue='cancel';d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true}));}
async function start(mode,ids,minutes=0){if(!ids.length){toast('当前没有可练习的题目。');return;}if(state.session&&!state.session.completed){if(!await confirm('开始新的练习？','上次未完成的练习将被替换，已经提交的答题记录会保留。'))return;}state.session=C.newSession(mode,ids,minutes,mode==='mock'?($('#mock-feedback')?.value||'immediate'):'immediate');reviewExam=null;save();if(location.hash==='#quiz')render();else location.hash='quiz';window.scrollTo(0,0);}
function finishExam(reason){const e=C.finishMock(state,B,reason);if(e){save();reviewExam=e;location.hash='result';render();toast(reason==='timeout'?'计时结束，已自动交卷。':'模拟已提交，错题已记录。');}}
async function action(a,v){const s=state.session;switch(a){case'all':start('all',B.map(q=>q.id));break;case'filtered':start('all',filtered().map(q=>q.id));break;case'random':start('random',C.shuffle(filtered()).slice(0,20).map(q=>q.id));break;case'topic':start('topic',B.filter(q=>q.category===v).map(q=>q.id));break;case'single':start('topic',[v]);break;case'resume':location.hash='quiz';break;case'new-mock':start('mock',C.mockQuestions(B),Number($('#exam-time')?.value||0));break;case'answer':{if(!s||s.completed||location.hash!=='#quiz')return;const q=byId[s.ids[s.index]],ans=Number(v);if(!Number.isInteger(ans)||ans<0||ans>3)return;if(s.mode==='mock'&&s.deadline&&Date.now()>=s.deadline){finishExam('timeout');return;}if(s.mode==='mock'&&s.feedback!=='immediate'){if(s.deadline&&Date.now()>=s.deadline){finishExam('timeout');return;}s.answers[q.id]=ans;}else C.answerPractice(state,B,q.id,ans);save();render();if(s.mode!=='mock'||s.feedback==='immediate')revealFeedback();break;}case'enable-feedback':if(C.enableImmediateFeedback(state,B)){save();render();revealFeedback();toast('已开启即时解析；已选答案已锁定。');}break;case'next':if(s&&s.index<s.ids.length-1){s.index++;save();render();window.scrollTo(0,0);}break;case'prev':if(s&&s.index>0){s.index--;save();render();window.scrollTo(0,0);}break;case'map':$('.quiz-map')?.classList.toggle('open');$('.quiz-map')?.scrollIntoView({behavior:'smooth',block:'start'});break;case'jump':if(s){s.index=Math.min(s.ids.length-1,Math.max(0,Number(v)));save();render();}break;case'exit':location.hash='practice';break;case'finish':{const left=s.ids.filter(id=>!s.recorded[id]).length;if(left&&!await confirm('结束这轮练习？',`还有 ${left} 题未作答。结束后可重新开始，已完成记录会保留。`))return;s.completed=true;save();location.hash='stats';toast('本轮练习已保存。');break;}case'submit':{const left=s.ids.filter(id=>s.answers[id]===undefined).length;if(await confirm('确认交卷？',left?`还有 ${left} 题未作答，将按答错计分并加入错题本。`:'交卷后显示成绩与全部解析。'))finishExam('manual');break;}case'star':{const i=state.stars.indexOf(v);if(i<0)state.stars.push(v);else state.stars.splice(i,1);save();render();toast(i<0?'已收藏':'已取消收藏');break;}case'wrong-active':wrongArchived=false;render();break;case'wrong-archived':wrongArchived=true;render();break;case'wrong-start':start('wrong',C.shuffle(wrongIds(wrongArchived)));break;case'stars':start('stars',state.stars.filter(id=>byId[id]));break;case'star-list':filter.source='stars';filter.progress='all';location.hash='library';break;case'page-prev':listPage=Math.max(1,listPage-1);render();window.scrollTo(0,0);break;case'page-next':listPage++;render();window.scrollTo(0,0);break;case'history':reviewExam=state.exams.find(e=>e.id===v);location.hash='result';break;case'review':reviewIndex=0;location.hash='review';break;case'review-prev':reviewIndex=Math.max(0,reviewIndex-1);render();window.scrollTo(0,0);break;case'review-next':reviewIndex=Math.min((reviewExam||s.result).ids.length-1,reviewIndex+1);render();window.scrollTo(0,0);break;case'exam-wrong':{const e=reviewExam||s?.result;start('wrong',e.ids.filter(id=>e.answers[id]!==byId[id].answer));break;}case'raw':rawFocus=v;if(location.hash==='#original')originals(v);else location.hash='original';break;case'original':rawFocus=null;if(location.hash==='#original')originals();else location.hash='original';break;case'raw-search':rawFocus=null;filter.search=$('#raw-search').value;originals();break;case'export':download(JSON.stringify(state,null,2),'NJ-Drive-学习备份-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('学习记录已导出。');break;case'import':$('#import-file').click();break;case'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('请用浏览器菜单的“安装应用”或“添加到主屏幕”。');break;case'reset':if(await confirm('清空本机学习记录？','将清空答题、错题、收藏和模拟记录。建议先导出备份，之后可用备份恢复。')){state=C.fresh();save();render();toast('本机学习记录已清空。');}break;}}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action,b.dataset.value).catch(err=>toast('操作未完成，请重试或导出备份。'));});
document.addEventListener('change',async e=>{const id=e.target.id;if(id==='language'){state.language=e.target.value;save();render();}else if(['category','source-filter','progress-filter'].includes(id)){filter[id==='source-filter'?'source':id==='progress-filter'?'progress':'category']=e.target.value;listPage=1;render();}else if(id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('备份文件过大');const imported=C.validateImport(JSON.parse(await file.text()),B);if(await confirm('导入并替换当前学习记录？','已读入有效备份。当前答题、收藏和成绩将被替换；未完成的练习不导入。')){state=imported;save();render();toast('备份已恢复。');}}catch(err){toast(err.message||'无法读取此备份。');}}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){filter.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;listPage=1;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);},250);}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
setInterval(()=>{const s=state.session;if(s?.mode==='mock'&&!s.completed&&s.deadline){if(Date.now()>=s.deadline)finishExam('timeout');else if($('#timer'))$('#timer').textContent=timeLeft(s);}},1000);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){toast('另一标签页已更新记录，请刷新后继续，避免覆盖。');}});
async function cacheStatus(){const el=$('#cache-status');if(!el)return;try{if(!('serviceWorker'in navigator)){el.textContent='此浏览器不支持离线安装。';return;}const reg=await navigator.serviceWorker.getRegistration();const keys=await caches.keys();let cached=false;for(const k of keys.filter(k=>k.startsWith('nj-drive-'))){const cache=await caches.open(k);if(await cache.match('index.html'))cached=true;}el.textContent=cached?'离线资源已缓存。清除浏览器数据前请先备份。':reg?'资源正在首次缓存，请保持联网片刻。':'请通过 HTTPS 正式网址或本机预览打开，以启用离线功能。';}catch(e){el.textContent='当前环境无法读取离线缓存状态。';}}
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(reg=>{reg.update().catch(()=>{});reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='activated'&&navigator.serviceWorker.controller)toast('有新版本可用，刷新后即可使用新版解析。');});});if(location.hash==='#settings')cacheStatus();}).catch(()=>{});
render();const active=state.session;if(active?.mode==='mock'&&!active.completed&&active.deadline&&Date.now()>=active.deadline)finishExam('timeout');
})();
